	    FROM OAUTH2_TOKEN

INSERT INTO OAUTH2_TOKEN (
		SOCIAL_MEM_ID
		, SOCIAL_MEM_USER
		, SOCIAL_MEM_TOKEN_TYPE
		, SOCIAL_MEM_TOKEN
		, TOKEN_CREATE
		, TOKEN_FINISH
		, TOKEN_REFRESH
		, TOKEN_REFRESH_TIME
	) VALUES (
	#{socialMemId}
		, #{socialMemUser}
		, #{socialMemTokenType}
		, #{socialMemToken}
		, SYSDATE, 
		, #{tokenFinish}
		, #{tokenRefresh}
