UPDATE OAUTH2_TOKEN
SET 
	SOCIAL_MEM_USER = #{socialMemUser}
	, SOCIAL_MEM_TOKEN_TYPE = #{socialMemTokenType}
	, SOCIAL_MEM_TOKEN = #{socialMemToken}
	, TOKEN_CREATE = #{tokenCreate}
	, TOKEN_FINISH = #{tokenFinish}
	, TOKEN_REFRESH = #{tokenRefresh}
	, TOKEN_REFRESH_TIME = #{tokenRefreshTime}
WHERE SOCIAL_MEM_ID = #{socialMemId}
